(()=>{
const q=s=>document.querySelector(s),key='ember-food-demo-v1';
const foods={casserole:{name:'Сирна запіканка',v:[140,16,4,10]},quiche:{name:'Кіш із лососем',v:[260,14,16,14]},roast:{name:'Жарке',v:[150,10,7,12]},bread:{name:'Хліб',v:[240,8,3,45]}};
const scenarios=['Знайома страва','Зміна рецепта','Приблизно','Усе ввечері','Обід наперед'];
let records=[],mode=0,editing=null,deleted=null;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))records=saved.filter(r=>r&&typeof r.id==='string'&&typeof r.name==='string'&&Array.isArray(r.values)&&r.values.length===4&&r.values.every(Number.isFinite)&&['eaten','planned'].includes(r.state))}catch{toast('Не вдалося прочитати локальні записи. Порожній щоденник готовий до роботи.')}
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));records=next;return true}catch{toast('Не вдалося зберегти. Чернетка залишилась на екрані.');return false}}
const portion=(id,value)=>`<label>Порція, г<input id="${id}" type="number" min="1" max="5000" step="1" value="${value}" required></label>`;
function choose(i){mode=i;editing=null;q('#cancel').hidden=true;q('#save').textContent='Зберегти запис';q('#scenario-title').textContent=scenarios[i];q('#date').value=today();q('#state').value=i===4?'planned':'eaten';
q('#hint').textContent=['Звична страва вже тут. Зміни лише порцію.','Демо двох готових варіантів рецепта. Попередні записи залишаться незмінними.','Коли грамів немає, можна зберегти власну приблизну оцінку.','Приклад: «Кіш 50, запіканка 100, жарке 450, хліб 40». Перевір порції перед збереженням.','Обід зранку залишається планом, поки ти не підтвердиш, що поїв.'][i];
q('#fields').innerHTML=i===2?'<label>Що їв<input id="food-name" value="Замовлений обід" maxlength="100" required></label><label>Опис порції<input id="portion-note" value="Одна середня порція" maxlength="120" required></label><label>Твоя оцінка калорій<input id="estimate" type="number" min="1" max="10000" value="650" required></label><p class="muted">БЖВ невідомі — у підсумку позначимо їх як неповні.</p>':i===3?Object.entries(foods).map(([id,f],n)=>`<div class="batch-row"><span>${f.name}</span>${portion('batch-'+id,[100,50,450,40][n])}</div>`).join(''):i===1?'<label>Варіант запіканки<select id="recipe"><option value="base">Звична · демо v1</option><option value="yogurt">З йогуртом · демо v2</option></select></label>'+portion('grams',100):'<label>Страва<select id="food">'+Object.entries(foods).map(([id,f])=>`<option value="${id}" ${i===4&&id==='roast'?'selected':''}>${f.name}</option>`).join('')+'</select></label>'+portion('grams',i===4?450:100);
document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.scenario===i)));preview()}
function draft(){const common={date:q('#date').value,state:q('#state').value};const make=(f,g)=>({...common,name:f.name,grams:g,values:f.v.map(n=>Math.round(n*g/100)),approx:false});
if(mode===2)return [{...common,name:q('#food-name').value.trim(),note:q('#portion-note').value.trim(),values:[+q('#estimate').value,0,0,0],approx:true,unknownMacros:true}];
if(mode===3)return Object.entries(foods).map(([id,f])=>make(f,+q('#batch-'+id).value));
if(mode===1){const alt=q('#recipe').value==='yogurt';return [make({name:alt?'Запіканка з йогуртом · v2':'Сирна запіканка · v1',v:alt?[130,15,3,11]:foods.casserole.v},+q('#grams').value)]}
return [make(foods[q('#food').value],+q('#grams').value)]}
function preview(){if(editing)return;const rows=draft(),k=rows.reduce((a,r)=>a+r.values[0],0);q('#preview').textContent=`${q('#state').value==='planned'?'До плану':'До з’їденого'}: ${Number.isFinite(k)?k:0} ккал${mode===2?' · приблизно · БЖВ невідомі':' · демонстраційний розрахунок'}`}
function node(tag,text){const e=document.createElement(tag);e.textContent=text;return e}
function render(){const date=q('#journal-date').value,visible=records.filter(r=>r.date===date),eaten=visible.filter(r=>r.state==='eaten'),planned=visible.filter(r=>r.state==='planned');const sum=rows=>rows.reduce((a,r)=>a.map((v,i)=>v+r.values[i]),[0,0,0,0]);const t=sum(eaten);q('#totals').textContent=`З’їдено: ${t[0]} ккал · Б ${t[1]} / Ж ${t[2]} / В ${t[3]} г. У плані: ${sum(planned)[0]} ккал.${eaten.some(r=>r.unknownMacros)?' БЖВ неповні: є страви без цих даних.':''}${eaten.some(r=>r.approx)?' Є приблизні оцінки.':''}`;
q('#entries').replaceChildren();if(!visible.length)q('#entries').append(node('p','Поки порожньо. Додай першу страву вище.'));
for(const r of visible){const row=node('article','');row.className='entry-row';row.append(node('h3',r.name),node('p',`${r.state==='planned'?'Заплановано':'З’їдено'} · ${r.grams?r.grams+' г':r.note||'Порція'} · ${r.approx?'≈ ':''}${r.values[0]} ккал`));const actions=node('div','');actions.className='actions';function button(label,fn){const b=node('button',label);b.type='button';b.onclick=fn;actions.append(b)}
if(r.state==='planned')button('Я це з’їв',()=>{if(persist(records.map(x=>x.id===r.id?{...x,state:'eaten'}:x))){render();toast('План підтверджено. Підсумок оновлений.')}});
button('Змінити',()=>edit(r));button('Видалити',()=>{if(persist(records.filter(x=>x.id!==r.id))){deleted=r;q('#undo').hidden=false;render()}});row.append(actions);q('#entries').append(row)}}
function edit(r){editing=r;q('#scenario-title').textContent='Змінити запис';q('#hint').textContent='Зміна стосується тільки цього запису.';q('#fields').replaceChildren();const label=node('label',r.grams?'Порція, г':'Оцінка калорій');const input=node('input','');input.id='edit-value';input.type='number';input.min='1';input.max=r.grams?'5000':'10000';input.required=true;input.value=r.grams||r.values[0];label.append(input);q('#fields').append(label);q('#date').value=r.date;q('#state').value=r.state;q('#preview').textContent=r.name;q('#save').textContent='Зберегти зміни';q('#cancel').hidden=false;q('#entry').scrollIntoView({block:'start'});input.focus()}
q('#entry').oninput=preview;q('#entry').onchange=preview;q('#cancel').onclick=()=>choose(mode);
q('#entry').onsubmit=e=>{e.preventDefault();if(!q('#entry').reportValidity())return;const date=q('#date').value;let next;if(editing){const n=+q('#edit-value').value,f=editing.grams?n/editing.grams:n/editing.values[0];const updated={...editing,date,state:q('#state').value,values:editing.values.map(v=>Math.round(v*f))};if(editing.grams)updated.grams=n;next=records.map(r=>r.id===editing.id?updated:r)}else{const rows=draft();if(rows.some(r=>!r.name||!r.values.every(Number.isFinite)))return;next=[...records,...rows.map(r=>({...r,id:crypto.randomUUID(),createdAt:new Date().toISOString()}))]}
if(persist(next)){q('#journal-date').value=date;choose(mode);render();toast('Збережено в цьому браузері.');q('#save').disabled=true;setTimeout(()=>q('#save').disabled=false,700)}};
q('#undo').onclick=()=>{if(deleted&&persist([...records,deleted])){deleted=null;q('#undo').hidden=true;render()}};q('#journal-date').value=today();q('#journal-date').onchange=render;
scenarios.forEach((name,i)=>{const b=node('button',name);b.dataset.scenario=i;b.onclick=()=>choose(i);q('#scenarios').append(b)});q('#about').onclick=()=>toast('Демо взаємодій. Реального ШІ та синхронізації поки немає.');choose(0);render();
})();
